 activityDay:b=>{let n=['dom','seg','ter','qua','qui','sex','sáb'].indexOf(b.dataset.id),i=draft.otherDays.indexOf(n);i<0?draft.otherDays.push(n):draft.otherDays.splice(i,1);render()},
 activityGroup:b=>{let id=b.dataset.id,i=draft.otherGroups.indexOf(id);i<0?draft.otherGroups.push(id):draft.otherGroups.splice(i,1);render()},
 suggestGroups:()=>{alignGroups();render()},
 next:()=>{let error='';if(step===0&&!draft.goal)error='Escolha um objetivo.';if(step===3&&!draft.included.length)error='Selecione pelo menos um grupo.';if(step===2&&!commitHeight())return;if(step===6&&draft.equipmentReview.length)error='Confirme a revisão dos equipamentos.';let fields=[...document.querySelectorAll('[data-profile]')];if(fields.some(t=>!t.checkValidity()))error='Revise os campos destacados ou deixe os opcionais vazios.';if(error){$('#setup-error').innerHTML=`<p class="notice error">${error}</p>`;return}step=setupSteps()[setupSteps().indexOf(step)+1]??8;render(false)},
