 create:async()=>{try{validateProfile(profileMode?{...draft,equipmentReview:[]}:draft);if(profileMode){let active=state.sessions.some(s=>s.startedAt&&!s.finishedAt);show(`<h2>Como aplicar o perfil?</h2><p>Suas novas informações podem ser salvas sem alterar o plano atual. Para mudar os treinos, revise e gere um novo plano.</p>${active?'<p class="notice error">Há treino em andamento. Gerar outro plano remove o progresso não finalizado, preservando o histórico salvo.</p>':''}<div class="modalfoot"><button data-action="keepProfile">Manter plano atual</button><button class="primary" data-action="newProfilePlan">Gerar novo plano</button></div>`);return}let plan=generate(draft,lib);state.profile=normalizeProfile(draft);state.plan=plan;await write();sessionStorage.removeItem('pf-setup');profileMode=false;view='train';selectedDate=plan.calendar.find(d=>d.templateId)?.date||localDate();render(false)}catch(e){$('#setup-error').innerHTML=`<p class="notice error">${esc(e.message)}</p>`}},
 keepProfile:async()=>{changeProfile(state,draft);await write();sessionStorage.removeItem('pf-setup');close();profileMode=false;view='settings';render(false);toast('Perfil atualizado. O plano atual foi mantido.')},
 newProfilePlan:async()=>{try{let plan=generate(draft,lib);changeProfile(state,draft,plan);restEnd=0;await write();sessionStorage.removeItem('pf-setup');close();profileMode=false;view='train';selectedDate=plan.calendar.find(d=>d.templateId)?.date||localDate();render(false);toast('Novo plano criado. Histórico preservado.')}catch(e){close();$('#setup-error').innerHTML=`<p class="notice error">${esc(e.message)}</p>`}},
 personalNotes:()=>{let p=state.plan.profileSnapshot||state.profile;show(`<h2>Referências do perfil</h2><p class="muted">${[p.age!==''?p.age+' anos':'',p.height!==''?formatHeight(p.height)+' m':'',p.weight!==''?Number(p.weight).toLocaleString('pt-BR')+' kg':''].filter(Boolean).map(esc).join(' · ')||'Medidas não informadas.'}</p><p class="muted">Referências para ajuste de aparelhos e revisão, sem cálculo de carga.</p>${p.restrictions?`<h3>Limitações e orientações</h3><p>${esc(p.restrictions)}</p><p class="muted">A anotação não foi interpretada como diagnóstico ou reabilitação. Confira as exclusões e a seleção com um profissional.</p>`:''}${p.otherActivity?`<h3>Outras atividades</h3><p>${esc(p.otherActivity)}</p>`:''}`)},
